import type {
  DOMConversionMap,
  DOMExportOutput,
  EditorConfig,
  LexicalEditor,
  LexicalNode,
  NodeKey,
  SerializedLexicalNode,
  Spread,
} from "lexical"
import { $applyNodeReplacement, createCommand, DecoratorNode } from "lexical"
import { Check, Edit2, Sigma } from "lucide-react"
import * as React from "react"

export type SerializedEquationNode = Spread<
  {
    equation: string
    inline: boolean
  },
  SerializedLexicalNode
>

export const INSERT_EQUATION_COMMAND = createCommand<{
  equation: string
  inline?: boolean
}>("INSERT_EQUATION_COMMAND")

function EquationComponent({
  equation: initialEquation,
  inline,
  nodeKey,
}: {
  equation: string
  inline: boolean
  nodeKey: NodeKey
}) {
  const [equation, setEquation] = React.useState(initialEquation)
  const [isEditing, setIsEditing] = React.useState(false)
  const [draft, setDraft] = React.useState(initialEquation)

  const handleSave = () => {
    setEquation(draft)
    setIsEditing(false)
  }

  if (inline) {
    return (
      <span
        data-lexical-node={nodeKey}
        onClick={() => setIsEditing(true)}
        className="group relative mx-1 inline-flex cursor-pointer items-center gap-1 rounded-md border border-border/60 bg-muted/40 px-2 py-0.5 font-mono text-xs text-primary transition-all hover:border-primary/40 hover:bg-muted/70"
        title="Click to edit formula"
      >
        <Sigma className="size-3 text-primary/70" />
        <span>{equation}</span>
      </span>
    )
  }

  return (
    <div
      data-lexical-node={nodeKey}
      className="mx-auto my-4 max-w-xl rounded-xl border border-border/80 bg-card/70 p-4 shadow-md backdrop-blur-xs select-none"
    >
      <div className="mb-3 flex items-center justify-between border-b border-border/40 pb-2">
        <div className="flex items-center gap-2 text-xs font-semibold text-foreground">
          <Sigma className="size-4 text-primary" />
          <span>LaTeX Formula</span>
        </div>
        <button
          type="button"
          onClick={() => {
            setDraft(equation)
            setIsEditing((p) => !p)
          }}
          className="flex cursor-pointer items-center gap-1 text-[11px] text-muted-foreground hover:text-foreground"
        >
          <Edit2 className="size-3" />
          <span>{isEditing ? "Close" : "Edit"}</span>
        </button>
      </div>

      {isEditing ? (
        <div className="space-y-3">
          <textarea
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            rows={3}
            placeholder="Type LaTeX math formula (e.g. f(x) = \int_{-\infty}^{\infty} e^{-x^2} dx)..."
            className="w-full rounded-lg border border-border/70 bg-muted/30 p-2 font-mono text-xs text-foreground outline-none focus:ring-1 focus:ring-primary"
          />
          <div className="flex justify-end gap-2">
            <button
              type="button"
              onClick={() => setIsEditing(false)}
              className="cursor-pointer rounded-md border border-border/60 px-3 py-1 text-xs text-muted-foreground hover:bg-muted"
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={handleSave}
              className="flex cursor-pointer items-center gap-1 rounded-md bg-primary px-3 py-1 text-xs text-primary-foreground hover:bg-primary/90"
            >
              <Check className="size-3" />
              <span>Apply</span>
            </button>
          </div>
        </div>
      ) : (
        <div className="flex min-h-[50px] items-center justify-center overflow-x-auto rounded-lg bg-muted/20 p-4 font-mono text-sm tracking-wide text-foreground">
          {equation || "\\text{Empty equation}"}
        </div>
      )}
    </div>
  )
}

export class EquationNode extends DecoratorNode<React.JSX.Element> {
  __equation: string
  __inline: boolean

  static getType(): string {
    return "equation"
  }

  static clone(node: EquationNode): EquationNode {
    return new EquationNode(node.__equation, node.__inline, node.__key)
  }

  static importJSON(serializedNode: SerializedEquationNode): EquationNode {
    return $createEquationNode(serializedNode.equation, serializedNode.inline)
  }

  exportJSON(): SerializedEquationNode {
    return {
      equation: this.__equation,
      inline: this.__inline,
      type: "equation",
      version: 1,
    }
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement(this.__inline ? "span" : "div")
    element.setAttribute("data-lexical-equation", this.__equation)
    element.setAttribute("data-lexical-inline", `${this.__inline}`)
    element.innerText = this.__equation
    return { element }
  }

  static importDOM(): DOMConversionMap | null {
    return {
      div: (domNode: Node) => {
        if (domNode instanceof HTMLElement) {
          const eq = domNode.getAttribute("data-lexical-equation")
          if (eq) {
            return {
              conversion: () => ({ node: $createEquationNode(eq, false) }),
              priority: 1,
            }
          }
        }
        return null
      },
      span: (domNode: Node) => {
        if (domNode instanceof HTMLElement) {
          const eq = domNode.getAttribute("data-lexical-equation")
          if (eq) {
            return {
              conversion: () => ({ node: $createEquationNode(eq, true) }),
              priority: 1,
            }
          }
        }
        return null
      },
    }
  }

  constructor(equation: string, inline: boolean = false, key?: NodeKey) {
    super(key)
    this.__equation = equation
    this.__inline = inline
  }

  updateDOM(): false {
    return false
  }

  decorate(_editor: LexicalEditor, _config: EditorConfig): React.JSX.Element {
    return (
      <EquationComponent
        nodeKey={this.getKey()}
        equation={this.__equation}
        inline={this.__inline}
      />
    )
  }
}

export function $createEquationNode(
  equation: string,
  inline: boolean = false
): EquationNode {
  return $applyNodeReplacement(new EquationNode(equation, inline))
}

export function $isEquationNode(
  node: LexicalNode | null | undefined
): node is EquationNode {
  return node instanceof EquationNode
}

/* eslint-disable react-hooks/set-state-in-effect */
import type {
  ExcalidrawElement,
  NonDeleted,
} from "@excalidraw/excalidraw/element/types"
import type { AppState, BinaryFiles } from "@excalidraw/excalidraw/types"
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext"
import { useLexicalEditable } from "@lexical/react/useLexicalEditable"
import { useLexicalNodeSelection } from "@lexical/react/useLexicalNodeSelection"
import type { NodeKey } from "lexical"
import {
  $getNodeByKey,
  CLICK_COMMAND,
  COMMAND_PRIORITY_LOW,
  isDOMNode,
  mergeRegister,
} from "lexical"
import {
  AlignCenter,
  AlignLeft,
  AlignRight,
  Pencil,
  Trash2,
} from "lucide-react"
import * as React from "react"

import { useTheme } from "next-themes"

import { cn } from "../../utils/cn"
import { $isExcalidrawNode } from "../excalidraw-node"
import { ExcalidrawImage } from "./excalidraw-image"
import { ExcalidrawModal } from "./excalidraw-modal"
import type { Dimension, ExcalidrawNodeData } from "./types"

export interface ExcalidrawComponentProps {
  nodeKey: NodeKey
  data: string
  width?: Dimension
  height?: Dimension
  alignment?: "left" | "center" | "right"
}

export function ExcalidrawComponent({
  nodeKey,
  data,
  width = "inherit",
  height = "inherit",
  alignment = "center",
}: ExcalidrawComponentProps) {
  const [editor] = useLexicalComposerContext()
  const isEditable = useLexicalEditable()

  // Parse scene data safely
  const parsedData = React.useMemo<ExcalidrawNodeData>(() => {
    if (!data || data === "[]") return { elements: [], appState: {}, files: {} }
    try {
      return JSON.parse(data)
    } catch {
      return { elements: [], appState: {}, files: {} }
    }
  }, [data])

  const { elements = [], files = {}, appState = {} } = parsedData

  // If node was just inserted with empty data, immediately open modal for drawing
  const [isModalOpen, setIsModalOpen] = React.useState<boolean>(
    (!data || data === "[]" || elements.length === 0) && isEditable
  )
  const [isSelected, setSelected, clearSelection] =
    useLexicalNodeSelection(nodeKey)
  const [currentWidth, setCurrentWidth] = React.useState<Dimension>(width)
  const [currentAlign, setCurrentAlign] = React.useState<
    "left" | "center" | "right"
  >(alignment)
  const [isResizing, setIsResizing] = React.useState<boolean>(false)

  const containerRef = React.useRef<HTMLDivElement | null>(null)
  const isDraggingRef = React.useRef(false)
  const startXRef = React.useRef(0)
  const startWidthRef = React.useRef(0)

  // Track active theme dynamically
  const { theme } = useTheme()
  const isDark =
    theme === "dark" ||
    (theme === "system" &&
      typeof window !== "undefined" &&
      window.matchMedia("(prefers-color-scheme: dark)").matches)

  // Sync width & alignment from node
  React.useEffect(() => {
    setCurrentWidth(width)
  }, [width])

  React.useEffect(() => {
    setCurrentAlign(alignment)
  }, [alignment])

  // Click & selection handling
  React.useEffect(() => {
    if (!isEditable) {
      if (isSelected) clearSelection()
      return
    }

    return mergeRegister(
      editor.registerCommand(
        CLICK_COMMAND,
        (event: MouseEvent) => {
          const container = containerRef.current
          const eventTarget = event.target

          if (isResizing) return true

          if (
            container !== null &&
            isDOMNode(eventTarget) &&
            container.contains(eventTarget)
          ) {
            if (!event.shiftKey) {
              clearSelection()
            }
            setSelected(true)

            // Double click opens Excalidraw editor
            if (event.detail > 1) {
              setIsModalOpen(true)
            }
            return true
          }

          return false
        },
        COMMAND_PRIORITY_LOW
      )
    )
  }, [clearSelection, editor, isSelected, isResizing, setSelected, isEditable])

  const updateNodeData = React.useCallback(
    (
      newElements: readonly NonDeleted<ExcalidrawElement>[],
      newAppState: Partial<AppState>,
      newFiles: BinaryFiles
    ) => {
      editor.update(() => {
        const node = $getNodeByKey(nodeKey)
        if ($isExcalidrawNode(node)) {
          const nonDeleted = newElements.filter((el) => !el.isDeleted)
          if (nonDeleted.length > 0 || Object.keys(newFiles).length > 0) {
            node.setData(
              JSON.stringify({
                appState: newAppState,
                elements: nonDeleted,
                files: newFiles,
              })
            )
          } else {
            node.remove()
          }
        }
      })
    },
    [editor, nodeKey]
  )

  const updateNodeWidth = React.useCallback(
    (nextWidth: Dimension) => {
      setCurrentWidth(nextWidth)
      editor.update(() => {
        const node = $getNodeByKey(nodeKey)
        if ($isExcalidrawNode(node)) {
          node.setWidth(nextWidth)
        }
      })
    },
    [editor, nodeKey]
  )

  const updateNodeAlignment = React.useCallback(
    (nextAlign: "left" | "center" | "right") => {
      setCurrentAlign(nextAlign)
      editor.update(() => {
        const node = $getNodeByKey(nodeKey)
        if ($isExcalidrawNode(node)) {
          node.setAlignment(nextAlign)
        }
      })
    },
    [editor, nodeKey]
  )

  const deleteNode = React.useCallback(() => {
    setIsModalOpen(false)
    editor.update(() => {
      const node = $getNodeByKey(nodeKey)
      if (node) {
        node.remove()
      }
    })
  }, [editor, nodeKey])

  const closeModal = React.useCallback(() => {
    setIsModalOpen(false)
    if (elements.length === 0) {
      deleteNode()
    }
  }, [deleteNode, elements.length])

  // Drag resize handlers
  const handlePointerDownResize = (
    e: React.PointerEvent,
    direction: "left" | "right"
  ) => {
    e.preventDefault()
    e.stopPropagation()

    isDraggingRef.current = true
    startXRef.current = e.clientX

    const currentElemWidth =
      containerRef.current?.getBoundingClientRect().width || 600
    startWidthRef.current = currentElemWidth
    setIsResizing(true)

    const handlePointerMove = (moveEvent: PointerEvent) => {
      if (!isDraggingRef.current) return
      const deltaX =
        direction === "right"
          ? moveEvent.clientX - startXRef.current
          : startXRef.current - moveEvent.clientX

      const newWidth = Math.max(
        320,
        Math.min(1400, Math.round(startWidthRef.current + deltaX))
      )
      setCurrentWidth(newWidth)
    }

    const handlePointerUp = () => {
      if (isDraggingRef.current) {
        isDraggingRef.current = false
        window.removeEventListener("pointermove", handlePointerMove)
        window.removeEventListener("pointerup", handlePointerUp)

        setTimeout(() => setIsResizing(false), 150)
        const finalWidth =
          containerRef.current?.getBoundingClientRect().width ||
          startWidthRef.current
        updateNodeWidth(Math.round(finalWidth))
      }
    }

    window.addEventListener("pointermove", handlePointerMove)
    window.addEventListener("pointerup", handlePointerUp)
  }

  const alignmentClass = React.useMemo(() => {
    switch (currentAlign) {
      case "left":
        return "mr-auto ml-0"
      case "right":
        return "ml-auto mr-0"
      case "center":
      default:
        return "mx-auto"
    }
  }, [currentAlign])

  return (
    <>
      {isEditable && isModalOpen && (
        <ExcalidrawModal
          isShown={isModalOpen}
          initialElements={elements}
          initialAppState={appState}
          initialFiles={files}
          onDelete={deleteNode}
          onClose={closeModal}
          onSave={(els, aps, fls) => {
            updateNodeData(els, aps, fls)
            setIsModalOpen(false)
          }}
        />
      )}

      {elements.length > 0 && (
        <div
          ref={containerRef}
          data-lexical-node={nodeKey}
          onClick={() => setSelected(true)}
          tabIndex={0}
          className={cn(
            "group relative my-5 flex flex-col overflow-visible rounded-2xl border border-border/50 bg-card/40 shadow-xs transition-all outline-none select-none",
            alignmentClass,
            isSelected &&
              "shadow-md ring-2 ring-primary ring-offset-2 ring-offset-background"
          )}
          style={{
            width:
              typeof currentWidth === "number" ? `${currentWidth}px` : "100%",
          }}
        >
          {/* Floating Action Bar (Hover or Selected) */}
          {isEditable && (
            <div
              className={cn(
                "absolute -top-11 left-1/2 z-30 flex -translate-x-1/2 items-center gap-1 rounded-lg border border-border/70 bg-popover/95 px-1.5 py-1 shadow-lg backdrop-blur-md transition-all duration-150",
                isSelected
                  ? "pointer-events-auto scale-100 opacity-100"
                  : "pointer-events-none scale-95 opacity-0 group-hover:pointer-events-auto group-hover:scale-100 group-hover:opacity-100"
              )}
            >
              {/* Alignment controls */}
              <div className="flex items-center rounded-md bg-muted/60 p-0.5">
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation()
                    updateNodeAlignment("left")
                  }}
                  className={cn(
                    "cursor-pointer rounded p-1 text-muted-foreground transition-colors hover:text-foreground",
                    currentAlign === "left" &&
                      "bg-background font-semibold text-foreground shadow-2xs"
                  )}
                  title="Align left"
                >
                  <AlignLeft className="size-3.5" />
                </button>
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation()
                    updateNodeAlignment("center")
                  }}
                  className={cn(
                    "cursor-pointer rounded p-1 text-muted-foreground transition-colors hover:text-foreground",
                    currentAlign === "center" &&
                      "bg-background font-semibold text-foreground shadow-2xs"
                  )}
                  title="Align center"
                >
                  <AlignCenter className="size-3.5" />
                </button>
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation()
                    updateNodeAlignment("right")
                  }}
                  className={cn(
                    "cursor-pointer rounded p-1 text-muted-foreground transition-colors hover:text-foreground",
                    currentAlign === "right" &&
                      "bg-background font-semibold text-foreground shadow-2xs"
                  )}
                  title="Align right"
                >
                  <AlignRight className="size-3.5" />
                </button>
              </div>

              <div className="mx-0.5 h-3.5 w-px bg-border/60" />

              {/* Width presets */}
              <div className="flex items-center gap-0.5 text-[11px] font-medium">
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation()
                    updateNodeWidth(400)
                  }}
                  className={cn(
                    "cursor-pointer rounded px-1.5 py-0.5 whitespace-nowrap text-muted-foreground hover:bg-muted/60 hover:text-foreground",
                    currentWidth === 400 &&
                      "bg-primary/10 font-semibold text-primary"
                  )}
                >
                  Small
                </button>
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation()
                    updateNodeWidth(700)
                  }}
                  className={cn(
                    "cursor-pointer rounded px-1.5 py-0.5 whitespace-nowrap text-muted-foreground hover:bg-muted/60 hover:text-foreground",
                    currentWidth === 700 &&
                      "bg-primary/10 font-semibold text-primary"
                  )}
                >
                  Medium
                </button>
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation()
                    updateNodeWidth("inherit")
                  }}
                  className={cn(
                    "cursor-pointer rounded px-1.5 py-0.5 whitespace-nowrap text-muted-foreground hover:bg-muted/60 hover:text-foreground",
                    currentWidth === "inherit" &&
                      "bg-primary/10 font-semibold text-primary"
                  )}
                >
                  Full
                </button>
              </div>

              <div className="mx-0.5 h-3.5 w-px bg-border/60" />

              {/* Edit Excalidraw Button */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation()
                  setIsModalOpen(true)
                }}
                className="flex cursor-pointer items-center gap-1 rounded bg-primary/10 px-2 py-0.5 text-[11px] font-medium text-primary transition-colors hover:bg-primary/20"
                title="Edit drawing (or double-click)"
              >
                <Pencil className="size-3" />
                <span>Edit</span>
              </button>

              <div className="mx-0.5 h-3.5 w-px bg-border/60" />

              {/* Delete */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation()
                  deleteNode()
                }}
                className="cursor-pointer rounded p-1 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                title="Delete whiteboard"
              >
                <Trash2 className="size-3.5" />
              </button>
            </div>
          )}

          {/* Render Vector SVG Preview */}
          <ExcalidrawImage
            elements={elements}
            files={files}
            appState={appState}
            width={currentWidth}
            height={height}
            isDark={isDark}
            className="cursor-pointer"
          />

          {/* Interactive Drag Handles for Width Resizing */}
          {isSelected && isEditable && (
            <>
              <div
                onPointerDown={(e) => handlePointerDownResize(e, "left")}
                className="absolute top-1/2 -left-2 z-20 flex h-9 w-2.5 -translate-y-1/2 cursor-ew-resize items-center justify-center rounded-full border border-border/80 bg-background shadow-md transition-transform hover:scale-125 hover:bg-primary hover:text-white"
                title="Drag to resize width"
              >
                <div className="h-3 w-0.5 rounded-full bg-muted-foreground/60" />
              </div>
              <div
                onPointerDown={(e) => handlePointerDownResize(e, "right")}
                className="absolute top-1/2 -right-2 z-20 flex h-9 w-2.5 -translate-y-1/2 cursor-ew-resize items-center justify-center rounded-full border border-border/80 bg-background shadow-md transition-transform hover:scale-125 hover:bg-primary hover:text-white"
                title="Drag to resize width"
              >
                <div className="h-3 w-0.5 rounded-full bg-muted-foreground/60" />
              </div>
            </>
          )}
        </div>
      )}
    </>
  )
}

export default ExcalidrawComponent

import type {
  ExcalidrawElement,
  NonDeleted,
} from "@excalidraw/excalidraw/element/types"
import type { AppState, BinaryFiles } from "@excalidraw/excalidraw/types"
import * as React from "react"

import { cn } from "@/lib/utils"

import type { Dimension } from "./types"

interface ExcalidrawImageProps {
  elements: readonly NonDeleted<ExcalidrawElement>[]
  files?: BinaryFiles
  appState?: Partial<AppState>
  imageContainerRef?: React.RefObject<HTMLDivElement | null>
  width?: Dimension
  height?: Dimension
  className?: string
  isDark?: boolean
}

// exportToSvg includes double-sized width/height that need normalization with viewBox
const normalizeSvg = (svg: SVGElement) => {
  const viewBox = svg.getAttribute("viewBox")
  if (viewBox != null) {
    const viewBoxDimensions = viewBox.split(" ")
    if (viewBoxDimensions.length === 4) {
      svg.setAttribute("width", viewBoxDimensions[2])
      svg.setAttribute("height", viewBoxDimensions[3])
    }
  }
}

export function ExcalidrawImage({
  elements,
  files = {},
  imageContainerRef,
  appState = {},
  width = "inherit",
  height = "inherit",
  className,
  isDark = false,
}: ExcalidrawImageProps) {
  const [svgHtml, setSvgHtml] = React.useState<string>("")
  const [isLoading, setIsLoading] = React.useState<boolean>(true)

  React.useEffect(() => {
    let isSubscribed = true

    const generateSvg = async () => {
      try {
        if (!elements || elements.length === 0) {
          if (isSubscribed) {
            setSvgHtml("")
            setIsLoading(false)
          }
          return
        }

        setIsLoading(true)
        const { exportToSvg } = await import("@excalidraw/excalidraw")

        // Dynamic background adaptation: default light/dark backgrounds adapt to current theme
        const isDefaultBg =
          !appState.viewBackgroundColor ||
          appState.viewBackgroundColor === "#ffffff" ||
          appState.viewBackgroundColor === "#fff" ||
          appState.viewBackgroundColor === "#121212" ||
          appState.viewBackgroundColor === "#18181b"

        const effectiveBgColor = isDefaultBg
          ? isDark
            ? "#18181b"
            : "#ffffff"
          : appState.viewBackgroundColor

        // Clean & export SVG with active theme awareness
        const svg: SVGElement = await exportToSvg({
          appState: {
            ...appState,
            exportBackground: appState.exportBackground ?? true,
            viewBackgroundColor: effectiveBgColor,
            exportWithDarkMode: isDark,
          } as AppState,
          elements: elements as NonDeleted<ExcalidrawElement>[],
          files: files || {},
        })

        if (!isSubscribed) return

        normalizeSvg(svg)
        svg.setAttribute("display", "block")

        const clone = svg.cloneNode(true) as SVGElement
        clone.classList.add("excalidraw-canvas-svg")
        if (width === "inherit" && height === "inherit") {
          clone.style.maxWidth = "100%"
          clone.style.height = "auto"
          clone.style.display = "block"
          clone.style.margin = "0 auto"
        } else {
          clone.setAttribute("width", "100%")
          clone.setAttribute("height", "100%")
          clone.style.display = "block"
        }

        setSvgHtml(clone.outerHTML)
      } catch (err) {
        console.error("Failed to export Excalidraw drawing to SVG:", err)
      } finally {
        if (isSubscribed) {
          setIsLoading(false)
        }
      }
    }

    void generateSvg()

    return () => {
      isSubscribed = false
    }
  }, [elements, files, appState, width, height, isDark])

  const containerStyle: React.CSSProperties = React.useMemo(() => {
    const style: React.CSSProperties = {}
    if (width !== "inherit") {
      style.width = typeof width === "number" ? `${width}px` : width
    } else {
      style.width = "100%"
    }
    if (height !== "inherit") {
      style.height = typeof height === "number" ? `${height}px` : height
    }
    return style
  }, [width, height])

  return (
    <div
      ref={imageContainerRef}
      className={cn(
        "relative flex min-h-[140px] items-center justify-center overflow-hidden rounded-xl border border-border/40 bg-card/60 p-3 shadow-2xs transition-all",
        className
      )}
      style={containerStyle}
    >
      {isLoading && (
        <div className="backdrop-blur-2xs absolute inset-0 flex items-center justify-center bg-card/50">
          <div className="size-5 animate-spin rounded-full border-2 border-primary border-t-transparent" />
        </div>
      )}

      {svgHtml ? (
        <div
          data-excalidraw-svg-container="true"
          className="pointer-events-none flex h-full w-full items-center justify-center select-none [&>svg]:h-auto [&>svg]:max-w-full [&>svg]:rounded-lg"
          dangerouslySetInnerHTML={{ __html: svgHtml }}
        />
      ) : (
        !isLoading && (
          <div className="flex flex-col items-center justify-center py-8 text-xs text-muted-foreground">
            <span>Empty drawing</span>
          </div>
        )
      )}
    </div>
  )
}

