            <a
              href={src}
              target="_blank"
              rel="noreferrer"
              className="rounded-md bg-white/10 p-1.5 text-white transition-colors hover:bg-white/20"
              title="Open in new tab"
            >
              <ExternalLink className="size-4" />
            </a>
            <button
