  altText,
  nodeKey,
  width,
  maxWidth,
  caption,
  alignment = "center",
}: {
  src: string
  altText: string
  nodeKey: NodeKey
  width?: number | "inherit"
  maxWidth: number
  caption?: string
  alignment?: "left" | "center" | "right"
}) {
  const [editor] = useLexicalComposerContext()
  const [isSelected, setIsSelected] = React.useState(false)
  const [imageWidth, setImageWidth] = React.useState<number | "inherit">(
    width || "inherit"
  )
  const [currentAlign, setCurrentAlign] = React.useState<
    "left" | "center" | "right"
  >(alignment)
  const [captionText, setCaptionText] = React.useState(caption || "")
  const [isEditingCaption, setIsEditingCaption] = React.useState(false)
  const [isLightboxOpen, setIsLightboxOpen] = React.useState(false)
  const [isCopied, setIsCopied] = React.useState(false)

  const containerRef = React.useRef<HTMLDivElement>(null)
  const isDraggingRef = React.useRef(false)
  const startXRef = React.useRef(0)
  const startWidthRef = React.useRef(0)

  // Sync with node props
  React.useEffect(() => {
    setImageWidth(width || "inherit")
  }, [width])

  React.useEffect(() => {
    setCurrentAlign(alignment)
  }, [alignment])

  const updateNodeWidth = React.useCallback(
    (newWidth: number | "inherit") => {
      setImageWidth(newWidth)
      editor.update(() => {
        const node = $getNodeByKey(nodeKey)
        if ($isImageNode(node)) {
          node.setWidthAndHeight(newWidth, "inherit")
        }
      })
    },
    [editor, nodeKey]
  )

  const updateNodeAlignment = React.useCallback(
    (newAlign: "left" | "center" | "right") => {
      setCurrentAlign(newAlign)
      editor.update(() => {
        const node = $getNodeByKey(nodeKey)
        if ($isImageNode(node)) {
          node.setAlignment(newAlign)
        }
      })
    },
    [editor, nodeKey]
  )

  const handleSaveCaption = React.useCallback(() => {
    setIsEditingCaption(false)
    editor.update(() => {
      const node = $getNodeByKey(nodeKey)
      if ($isImageNode(node)) {
        node.setCaption(captionText)
      }
    })
  }, [editor, nodeKey, captionText])

  const handleDelete = React.useCallback(() => {
    editor.update(() => {
      const node = $getNodeByKey(nodeKey)
      if (node) {
        node.remove()
      }
    })
  }, [editor, nodeKey])

  const handleCopyLink = React.useCallback(() => {
    navigator.clipboard.writeText(src)
    setIsCopied(true)
    setTimeout(() => setIsCopied(false), 1500)
  }, [src])

  // Drag resize handlers
  const handlePointerDownResize = (
    e: React.PointerEvent,
    direction: "left" | "right"
  ) => {
    e.preventDefault()
    e.stopPropagation()

    isDraggingRef.current = true
    startXRef.current = e.clientX

    const currentElemWidth =
      containerRef.current?.getBoundingClientRect().width || 400
    startWidthRef.current = currentElemWidth

    const handlePointerMove = (moveEvent: PointerEvent) => {
      if (!isDraggingRef.current) return
      const deltaX =
        direction === "right"
          ? moveEvent.clientX - startXRef.current
          : startXRef.current - moveEvent.clientX

      const newCalculatedWidth = Math.max(
        200,
        Math.min(1200, Math.round(startWidthRef.current + deltaX))
      )
      setImageWidth(newCalculatedWidth)
    }

    const handlePointerUp = () => {
      if (isDraggingRef.current) {
        isDraggingRef.current = false
        window.removeEventListener("pointermove", handlePointerMove)
        window.removeEventListener("pointerup", handlePointerUp)

        const finalWidth =
          containerRef.current?.getBoundingClientRect().width ||
          startWidthRef.current
        updateNodeWidth(Math.round(finalWidth))
      }
    }

    window.addEventListener("pointermove", handlePointerMove)
    window.addEventListener("pointerup", handlePointerUp)
  }

  const alignmentClass = React.useMemo(() => {
    switch (currentAlign) {
      case "left":
        return "mr-auto ml-0"
      case "right":
        return "ml-auto mr-0"
      case "center":
      default:
        return "mx-auto"
    }
  }, [currentAlign])

  return (
    <>
      <div
        ref={containerRef}
        data-lexical-node={nodeKey}
        onClick={() => setIsSelected(true)}
        onBlur={(e) => {
          // If clicked inside, don't unselect
          if (containerRef.current?.contains(e.relatedTarget)) return
          setIsSelected(false)
        }}
        tabIndex={0}
        className={cn(
          "group relative my-4 flex flex-col overflow-visible rounded-xl border border-border/50 bg-card/60 shadow-xs transition-all outline-none select-none",
          alignmentClass,
          isSelected &&
            "shadow-md ring-2 ring-primary ring-offset-2 ring-offset-background"
        )}
        style={{
          width: typeof imageWidth === "number" ? `${imageWidth}px` : "100%",
          maxWidth: maxWidth ? `${maxWidth}px` : "100%",
        }}
      >
        {/* Floating Action Bar (Hover or Selected) */}
        <div
          className={cn(
            "absolute -top-11 left-1/2 z-30 flex -translate-x-1/2 items-center gap-1 rounded-lg border border-border/70 bg-popover/95 px-1.5 py-1 shadow-lg backdrop-blur-md transition-all duration-150",
            isSelected
              ? "pointer-events-auto scale-100 opacity-100"
              : "pointer-events-none scale-95 opacity-0 group-hover:pointer-events-auto group-hover:scale-100 group-hover:opacity-100"
          )}
        >
          {/* Alignment controls */}
          <div className="flex items-center rounded-md bg-muted/60 p-0.5">
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation()
                updateNodeAlignment("left")
              }}
              className={cn(
                "cursor-pointer rounded p-1 text-muted-foreground transition-colors hover:text-foreground",
                currentAlign === "left" &&
                  "bg-background font-semibold text-foreground shadow-2xs"
              )}
              title="Align left"
            >
              <AlignLeft className="size-3.5" />
            </button>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation()
                updateNodeAlignment("center")
              }}
              className={cn(
                "cursor-pointer rounded p-1 text-muted-foreground transition-colors hover:text-foreground",
                currentAlign === "center" &&
                  "bg-background font-semibold text-foreground shadow-2xs"
              )}
              title="Align center"
            >
              <AlignCenter className="size-3.5" />
            </button>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation()
                updateNodeAlignment("right")
              }}
              className={cn(
                "cursor-pointer rounded p-1 text-muted-foreground transition-colors hover:text-foreground",
                currentAlign === "right" &&
                  "bg-background font-semibold text-foreground shadow-2xs"
              )}
              title="Align right"
            >
              <AlignRight className="size-3.5" />
            </button>
          </div>

          <div className="mx-0.5 h-3.5 w-px bg-border/60" />

          {/* Width presets */}
          <div className="flex items-center gap-0.5 text-[11px] font-medium">
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation()
                updateNodeWidth(320)
              }}
              className={cn(
                "cursor-pointer rounded px-1.5 py-0.5 whitespace-nowrap text-muted-foreground hover:bg-muted/60 hover:text-foreground",
                imageWidth === 320 && "bg-primary/10 font-semibold text-primary"
              )}
            >
              Small
            </button>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation()
                updateNodeWidth(600)
              }}
              className={cn(
                "cursor-pointer rounded px-1.5 py-0.5 whitespace-nowrap text-muted-foreground hover:bg-muted/60 hover:text-foreground",
                imageWidth === 600 && "bg-primary/10 font-semibold text-primary"
              )}
            >
              Medium
            </button>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation()
                updateNodeWidth("inherit")
              }}
              className={cn(
                "cursor-pointer rounded px-1.5 py-0.5 whitespace-nowrap text-muted-foreground hover:bg-muted/60 hover:text-foreground",
                imageWidth === "inherit" &&
                  "bg-primary/10 font-semibold text-primary"
              )}
            >
              Full
            </button>
          </div>

          <div className="mx-0.5 h-3.5 w-px bg-border/60" />

          {/* Quick utility actions */}
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation()
              setIsLightboxOpen(true)
            }}
            className="cursor-pointer rounded p-1 text-muted-foreground hover:bg-muted/60 hover:text-foreground"
            title="View Fullscreen Lightbox"
          >
            <Maximize2 className="size-3.5" />
          </button>

          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation()
              handleCopyLink()
            }}
            className="cursor-pointer rounded p-1 text-muted-foreground hover:bg-muted/60 hover:text-foreground"
            title="Copy image link"
          >
            {isCopied ? (
              <Check className="size-3.5 text-emerald-500" />
            ) : (
              <Copy className="size-3.5" />
            )}
          </button>

          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation()
              handleDelete()
            }}
            className="cursor-pointer rounded p-1 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
            title="Delete image"
          >
            <Trash2 className="size-3.5" />
          </button>
        </div>

        {/* Main Image Container */}
        <div className="relative w-full overflow-hidden rounded-t-xl bg-muted/20">
          <img
            src={src}
            alt={altText}
            className="h-auto w-full max-w-full cursor-pointer object-contain transition-transform duration-200"
            loading="lazy"
            onClick={() => setIsSelected(true)}
            onDoubleClick={() => setIsLightboxOpen(true)}
          />

          {/* Left Resize Drag Handle */}
          {isSelected && (
            <div
              onPointerDown={(e) => handlePointerDownResize(e, "left")}
              className="absolute top-1/2 left-1 flex h-10 w-2.5 -translate-y-1/2 cursor-ew-resize items-center justify-center rounded-full bg-primary/80 shadow-md transition-colors hover:bg-primary"
              title="Drag to resize width"
            >
              <div className="h-4 w-0.5 rounded-full bg-white/80" />
            </div>
          )}

          {/* Right Resize Drag Handle */}
          {isSelected && (
            <div
              onPointerDown={(e) => handlePointerDownResize(e, "right")}
              className="absolute top-1/2 right-1 flex h-10 w-2.5 -translate-y-1/2 cursor-ew-resize items-center justify-center rounded-full bg-primary/80 shadow-md transition-colors hover:bg-primary"
              title="Drag to resize width"
            >
              <div className="h-4 w-0.5 rounded-full bg-white/80" />
            </div>
          )}
        </div>

        {/* Caption Bar */}
        <div className="border-t border-border/40 bg-card/60 px-3 py-1.5 text-center">
          {isEditingCaption ? (
            <input
              type="text"
              value={captionText}
              placeholder="Write a caption..."
              onChange={(e) => setCaptionText(e.target.value)}
              onBlur={handleSaveCaption}
              onKeyDown={(e) => {
                if (e.key === "Enter") handleSaveCaption()
              }}
              autoFocus
              className="w-full bg-transparent text-center text-xs text-muted-foreground outline-none focus:text-foreground"
            />
          ) : (
            <p
              onClick={(e) => {
                e.stopPropagation()
                setIsEditingCaption(true)
              }}
              className="cursor-pointer text-xs text-muted-foreground/75 transition-colors hover:text-foreground"
              title="Click to edit caption"
            >
              {captionText || "Add a caption…"}
            </p>
          )}
        </div>
      </div>

      {/* Fullscreen Lightbox Modal */}
      {isLightboxOpen && (
        <ImageLightbox
          src={src}
          altText={altText || captionText || "Image"}
          onClose={() => setIsLightboxOpen(false)}
        />
      )}
    </>
  )
}

export class ImageNode extends DecoratorNode<React.JSX.Element> {
  __src: string
  __altText: string
  __width: "inherit" | number
  __height: "inherit" | number
  __maxWidth: number
  __showCaption: boolean
  __caption?: string
  __alignment: "left" | "center" | "right"

  static getType(): string {
    return "image"
  }

  static clone(node: ImageNode): ImageNode {
    return new ImageNode(
      node.__src,
      node.__altText,
      node.__maxWidth,
      node.__width,
      node.__height,
      node.__showCaption,
      node.__caption,
      node.__alignment,
      node.__key
    )
  }

  static importJSON(serializedNode: SerializedImageNode): ImageNode {
    const {
      altText,
      height,
      width,
      maxWidth,
      caption,
      src,
      showCaption,
      alignment,
    } = serializedNode
    return $createImageNode({
      altText,
      height,
      maxWidth,
      showCaption,
      src,
      width,
      caption,
      alignment: alignment || "center",
    })
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement("img")
    element.setAttribute("src", this.__src)
    element.setAttribute("alt", this.__altText)
    if (this.__width) {
      element.setAttribute("width", this.__width.toString())
    }
    if (this.__height) {
      element.setAttribute("height", this.__height.toString())
    }
    return { element }
  }

  static importDOM(): DOMConversionMap | null {
    return {
      img: () => ({
        conversion: (domNode: Node): DOMConversionOutput | null => {
          if (domNode instanceof HTMLImageElement) {
            const { src, alt, width, height } = domNode
            const node = $createImageNode({
              altText: alt,
              height: height || undefined,
              src,
              width: width || undefined,
            })
            return { node }
          }
          return null
        },
        priority: 0,
      }),
    }
  }

  constructor(
    src: string,
    altText: string,
    maxWidth: number = 800,
    width?: "inherit" | number,
    height?: "inherit" | number,
    showCaption: boolean = true,
    caption?: string,
    alignment: "left" | "center" | "right" = "center",
    key?: NodeKey
  ) {
    super(key)
    this.__src = src
    this.__altText = altText
    this.__maxWidth = maxWidth
    this.__width = width || "inherit"
    this.__height = height || "inherit"
    this.__showCaption = showCaption
    this.__caption = caption
    this.__alignment = alignment
  }

  exportJSON(): SerializedImageNode {
    return {
      altText: this.getAltText(),
      caption: this.__caption,
      height: this.__height === "inherit" ? 0 : this.__height,
      maxWidth: this.__maxWidth,
      showCaption: this.__showCaption,
      src: this.getSrc(),
      type: "image",
      version: 1,
      width: this.__width === "inherit" ? 0 : this.__width,
      alignment: this.__alignment,
    }
  }

  getSrc(): string {
    return this.__src
  }

  getAltText(): string {
    return this.__altText
  }

  getCaption(): string | undefined {
    return this.getLatest().__caption
  }

  getAlignment(): "left" | "center" | "right" {
    return this.__alignment
  }

  setAlignment(alignment: "left" | "center" | "right"): void {
    const writable = this.getWritable()
    writable.__alignment = alignment
  }

  setWidthAndHeight(
    width: "inherit" | number,
    height: "inherit" | number
  ): void {
    const writable = this.getWritable()
    writable.__width = width
    writable.__height = height
  }

  setCaption(caption: string): void {
    const writable = this.getWritable()
    writable.__caption = caption
  }

  createDOM(config: EditorConfig): HTMLElement {
    const span = document.createElement("span")
    const theme = config.theme
    const className = theme.image
    if (className !== undefined) {
      span.className = className
    }
    return span
  }

  updateDOM(): false {
    return false
  }

  decorate(_editor: LexicalEditor, _config: EditorConfig): React.JSX.Element {
    return (
      <ImageComponent
        src={this.__src}
        altText={this.__altText}
        width={this.__width}
        maxWidth={this.__maxWidth}
        nodeKey={this.getKey()}
        caption={this.__caption}
        alignment={this.__alignment}
      />
    )
  }
}

export function $createImageNode({
  altText,
  height,
  maxWidth = 800,
  src,
  width,
  showCaption = true,
  caption,
  alignment = "center",
  key,
}: ImagePayload): ImageNode {
  return $applyNodeReplacement(
    new ImageNode(
      src,
      altText,
      maxWidth,
      width,
      height,
      showCaption,
      caption,
      alignment,
      key
    )
  )
}

export function $isImageNode(
  node: LexicalNode | null | undefined
): node is ImageNode {
  return node instanceof ImageNode
}

/* eslint-disable @typescript-eslint/no-unused-vars */
import type {
  DOMConversionMap,
  DOMExportOutput,
  EditorConfig,
  LexicalNode,
  NodeKey,
  SerializedElementNode,
  Spread,
} from "lexical"
import {
  $applyNodeReplacement,
  createCommand,
  ElementNode,
  isHTMLElement,
} from "lexical"

export type LayoutGap = "compact" | "normal" | "relaxed"
export type LayoutBorder = "dashed" | "card" | "clean"

export interface InsertLayoutPayload {
  templateColumns: string
  gap?: LayoutGap
  borderStyle?: LayoutBorder
}

export interface UpdateLayoutPayload {
  containerKey: NodeKey
  templateColumns?: string
  gap?: LayoutGap
  borderStyle?: LayoutBorder
}

export type SerializedLayoutContainerNode = Spread<
  {
    templateColumns: string
    gap?: LayoutGap
    borderStyle?: LayoutBorder
  },
  SerializedElementNode
>

export const INSERT_LAYOUT_COMMAND = createCommand<
  InsertLayoutPayload | string
>("INSERT_LAYOUT_COMMAND")

export const OPEN_LAYOUT_DIALOG_COMMAND = createCommand<void>(
  "OPEN_LAYOUT_DIALOG_COMMAND"
)

export const UPDATE_LAYOUT_COMMAND = createCommand<UpdateLayoutPayload>(
  "UPDATE_LAYOUT_COMMAND"
)

// 1. Layout Container
export class LayoutContainerNode extends ElementNode {
  __templateColumns: string
  __gap: LayoutGap
  __borderStyle: LayoutBorder

  static getType(): string {
    return "layout-container"
  }

  static clone(node: LayoutContainerNode): LayoutContainerNode {
    return new LayoutContainerNode(
      node.__templateColumns,
      node.__gap,
      node.__borderStyle,
      node.__key
    )
  }

  constructor(
    templateColumns: string = "1fr 1fr",
    gap: LayoutGap = "normal",
    borderStyle: LayoutBorder = "dashed",
    key?: NodeKey
  ) {
    super(key)
    this.__templateColumns = templateColumns
    this.__gap = gap
    this.__borderStyle = borderStyle
  }

  getGapClass(): string {
    switch (this.__gap) {
      case "compact":
        return "gap-2"
      case "relaxed":
        return "gap-6"
      case "normal":
      default:
        return "gap-4"
    }
  }

  getBorderClasses(): string[] {
    switch (this.__borderStyle) {
      case "card":
        return [
          "border",
          "border-border/70",
          "bg-card/60",
          "shadow-xs",
          "p-3.5",
          "rounded-xl",
        ]
      case "clean":
        return [
          "border",
          "border-transparent",
          "hover:border-border/30",
          "p-2",
          "rounded-xl",
        ]
      case "dashed":
      default:
        return [
          "border",
          "border-dashed",
          "border-border/60",
          "p-3",
          "bg-muted/10",
          "rounded-xl",
        ]
    }
  }

  createDOM(_config: EditorConfig): HTMLElement {
    const dom = document.createElement("div")
    dom.style.gridTemplateColumns = this.__templateColumns
    dom.setAttribute("data-lexical-layout-container", "true")
    dom.setAttribute("data-gap", this.__gap)
    dom.setAttribute("data-border", this.__borderStyle)
    dom.classList.add(
      "layout-container",
      "grid",
      "my-4",
      "w-full",
      "transition-all",
      "duration-200",
      this.getGapClass(),
      ...this.getBorderClasses()
    )
    return dom
  }

  updateDOM(prevNode: LayoutContainerNode, dom: HTMLElement): boolean {
    if (prevNode.__templateColumns !== this.__templateColumns) {
      dom.style.gridTemplateColumns = this.__templateColumns
    }
    if (
      prevNode.__gap !== this.__gap ||
      prevNode.__borderStyle !== this.__borderStyle
    ) {
      dom.setAttribute("data-gap", this.__gap)
      dom.setAttribute("data-border", this.__borderStyle)
      dom.className = [
        "layout-container",
        "grid",
        "my-4",
        "w-full",
        "transition-all",
        "duration-200",
        this.getGapClass(),
        ...this.getBorderClasses(),
      ].join(" ")
    }
    return false
  }

  static importDOM(): DOMConversionMap | null {
    return {
      div: (domNode: Node) => {
        if (
          isHTMLElement(domNode) &&
          domNode.classList.contains("layout-container")
        ) {
          const style = domNode.style.gridTemplateColumns || "1fr 1fr"
          const gap =
            (domNode.getAttribute("data-gap") as LayoutGap) || "normal"
          const borderStyle =
            (domNode.getAttribute("data-border") as LayoutBorder) || "dashed"
          return {
            conversion: () => ({
              node: $createLayoutContainerNode(style, gap, borderStyle),
            }),
            priority: 2,
          }
        }
        return null
      },
    }
  }

  static importJSON(
    serializedNode: SerializedLayoutContainerNode
  ): LayoutContainerNode {
    const node = $createLayoutContainerNode(
      serializedNode.templateColumns,
      serializedNode.gap || "normal",
      serializedNode.borderStyle || "dashed"
    )
    node.setFormat(serializedNode.format)
    node.setIndent(serializedNode.indent)
    node.setDirection(serializedNode.direction)
    return node
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement("div")
    element.classList.add(
      "layout-container",
      this.getGapClass(),
      ...this.getBorderClasses()
    )
    element.style.gridTemplateColumns = this.__templateColumns
    element.setAttribute("data-gap", this.__gap)
    element.setAttribute("data-border", this.__borderStyle)
    return { element }
  }

  exportJSON(): SerializedLayoutContainerNode {
    return {
      ...super.exportJSON(),
      templateColumns: this.__templateColumns,
      gap: this.__gap,
      borderStyle: this.__borderStyle,
      type: "layout-container",
      version: 1,
    }
  }

  setTemplateColumns(templateColumns: string): void {
    const writable = this.getWritable()
    writable.__templateColumns = templateColumns
  }

  getTemplateColumns(): string {
    return this.getLatest().__templateColumns
  }

  setGap(gap: LayoutGap): void {
    const writable = this.getWritable()
    writable.__gap = gap
  }

  getGap(): LayoutGap {
    return this.getLatest().__gap
  }

  setBorderStyle(borderStyle: LayoutBorder): void {
    const writable = this.getWritable()
    writable.__borderStyle = borderStyle
  }

  getBorderStyle(): LayoutBorder {
    return this.getLatest().__borderStyle
  }
}

// 2. Layout Item (Column)
export class LayoutItemNode extends ElementNode {
  static getType(): string {
    return "layout-item"
  }

  static clone(node: LayoutItemNode): LayoutItemNode {
    return new LayoutItemNode(node.__key)
  }

  createDOM(_config: EditorConfig): HTMLElement {
    const dom = document.createElement("div")
    dom.setAttribute("data-lexical-layout-item", "true")
    dom.classList.add(
      "layout-item",
      "min-w-0",
      "rounded-lg",
      "border",
      "border-border/40",
      "bg-card/40",
      "p-3",
      "transition-colors",
      "focus-within:border-primary/40",
      "focus-within:bg-card/80"
    )
    return dom
  }

  updateDOM(): boolean {
    return false
  }

  static importJSON(serializedNode: SerializedElementNode): LayoutItemNode {
    const node = $createLayoutItemNode()
    node.setFormat(serializedNode.format)
    node.setIndent(serializedNode.indent)
    node.setDirection(serializedNode.direction)
    return node
  }

  exportJSON(): SerializedElementNode {
    return {
