        type="button"
        variant="ghost"
        size="icon-xs"
        onClick={() => editor.dispatchCommand(REDO_COMMAND, undefined)}
        className="size-7 text-muted-foreground hover:bg-muted hover:text-foreground"
        title="Redo"
      >
        <Redo2 className="size-3.5" />
      </Button>

      <ToolbarDivider />

      {/* Inline formats */}
