        type="button"
        variant="ghost"
        size="icon-xs"
        onClick={() => editor.dispatchCommand(FORMAT_TEXT_COMMAND, "bold")}
        className={`size-7 ${isBold ? "bg-foreground/10 font-bold text-foreground" : "text-muted-foreground hover:bg-muted hover:text-foreground"}`}
        title="Bold (Ctrl+B)"
