import {
  $createHeadingNode,
  $createQuoteNode,
  $isHeadingNode,
  $isQuoteNode,
} from "@lexical/rich-text"
import type { ElementNode, LexicalEditor, LexicalNode } from "lexical"
import {
  $createParagraphNode,
  $getNearestNodeFromDOMNode,
  $getRoot,
  $isElementNode,
  $isParagraphNode,
  $parseSerializedNode,
} from "lexical"
import {
  CheckSquare,
  ChevronDown,
  ChevronUp,
  Clipboard,
