import { $generateHtmlFromNodes } from "@lexical/html"
import { $convertToMarkdownString } from "@lexical/markdown"
import { OnChangePlugin } from "@lexical/react/LexicalOnChangePlugin"
import type { EditorState, LexicalEditor } from "lexical"
import { $getRoot } from "lexical"
import * as React from "react"

import { EDITOR_TRANSFORMERS } from "../../core/transformers"
import type { EditorChangeData } from "../../types"

export function OnChangeHandlerPlugin({
  onChange,
}: {
  onChange?: (data: EditorChangeData) => void
}) {
  const onChangeRef = React.useRef(onChange)
  onChangeRef.current = onChange

  const handleChange = React.useCallback(
    (editorState: EditorState, editor: LexicalEditor) => {
      if (!onChangeRef.current) return

      editorState.read(() => {
        const root = $getRoot()
        const text = root.getTextContent()
        const isEmpty = text.trim().length === 0 && root.getChildrenSize() <= 1

        const jsonState = editorState.toJSON()
        const json = JSON.stringify(jsonState)

        let html = ""
        try {
          html = $generateHtmlFromNodes(editor, null)
        } catch (e) {
          console.warn("[Editor] Failed to generate HTML:", e)
        }

        let markdown = ""
        try {
          markdown = $convertToMarkdownString(EDITOR_TRANSFORMERS)
        } catch (e) {
          console.warn("[Editor] Failed to generate Markdown:", e)
        }

        onChangeRef.current?.({
          json,
          state: jsonState as unknown as Record<string, unknown>,
          html,
          markdown,
          text,
          isEmpty,
        })
      })
    },
    []
  )

  if (!onChange) return null

  return <OnChangePlugin onChange={handleChange} ignoreSelectionChange />
}

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext"
import { $insertNodeToNearestRoot } from "@lexical/utils"
import { COMMAND_PRIORITY_EDITOR } from "lexical"
import * as React from "react"

import {
  $createPageBreakNode,
  INSERT_PAGE_BREAK_COMMAND,
} from "../../nodes/page-break-node"

export function PageBreakPlugin(): null {
  const [editor] = useLexicalComposerContext()

  React.useEffect(() => {
    return editor.registerCommand(
      INSERT_PAGE_BREAK_COMMAND,
      () => {
        editor.update(() => {
          $insertNodeToNearestRoot($createPageBreakNode())
        })
        return true
      },
      COMMAND_PRIORITY_EDITOR
    )
  }, [editor])

  return null
}

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext"
import { $insertNodeToNearestRoot } from "@lexical/utils"
import { COMMAND_PRIORITY_EDITOR } from "lexical"
import * as React from "react"

import type { PollOption } from "../../nodes/poll-node"
import { $createPollNode, INSERT_POLL_COMMAND } from "../../nodes/poll-node"

export function PollPlugin(): null {
  const [editor] = useLexicalComposerContext()

  React.useEffect(() => {
    return editor.registerCommand(
      INSERT_POLL_COMMAND,
      (payload) => {
        const { question, options } = payload
        const pollOptions: PollOption[] | undefined = options?.map(
          (text, idx) => ({
            text,
            uid: `${Date.now()}-${idx}`,
            votes: [],
          })
        )

        editor.update(() => {
          $insertNodeToNearestRoot($createPollNode(question, pollOptions))
        })
        return true
      },
      COMMAND_PRIORITY_EDITOR
    )
  }, [editor])

  return null
}

import {
  INSERT_CHECK_LIST_COMMAND,
  INSERT_ORDERED_LIST_COMMAND,
  INSERT_UNORDERED_LIST_COMMAND,
} from "@lexical/list"
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext"
import {
  COMMAND_PRIORITY_NORMAL,
  createCommand,
  KEY_DOWN_COMMAND,
} from "lexical"
import * as React from "react"

import {
  formatCode,
  formatHeading,
  formatParagraph,
  formatQuote,
  updateFontSize,
  UpdateFontSizeType,
} from "../toolbar/utils"
import { KeyboardShortcutsDialog } from "./shortcuts-dialog"

export const OPEN_SHORTCUTS_DIALOG_COMMAND = createCommand<void>(
  "OPEN_SHORTCUTS_DIALOG_COMMAND"
)

export function ShortcutsPlugin(): React.JSX.Element {
  const [editor] = useLexicalComposerContext()
  const [isDialogOpen, setIsDialogOpen] = React.useState(false)

  React.useEffect(() => {
    // 1. Open Dialog Command
    const unregisterOpenCommand = editor.registerCommand(
      OPEN_SHORTCUTS_DIALOG_COMMAND,
      () => {
        setIsDialogOpen(true)
        return true
      },
      COMMAND_PRIORITY_NORMAL
    )

    // 2. Register Hotkeys inside Lexical
    const unregisterKeyDown = editor.registerCommand(
      KEY_DOWN_COMMAND,
      (event: KeyboardEvent) => {
        const { key, altKey, ctrlKey, metaKey, shiftKey } = event
        const isModifier = ctrlKey || metaKey

        // Ctrl + / or Cmd + / -> Open Shortcuts Dialog
        if (isModifier && (key === "/" || key === "?")) {
          event.preventDefault()
          setIsDialogOpen(true)
          return true
        }

        // Ctrl + Alt + 0 -> Normal Paragraph
        if (isModifier && altKey && key === "0") {
          event.preventDefault()
          formatParagraph(editor)
          return true
        }

        // Ctrl + Alt + 1 -> Heading 1
        if (isModifier && altKey && key === "1") {
          event.preventDefault()
          formatHeading(editor, "", "h1")
          return true
        }

        // Ctrl + Alt + 2 -> Heading 2
        if (isModifier && altKey && key === "2") {
          event.preventDefault()
          formatHeading(editor, "", "h2")
          return true
        }

        // Ctrl + Alt + 3 -> Heading 3
        if (isModifier && altKey && key === "3") {
          event.preventDefault()
          formatHeading(editor, "", "h3")
          return true
        }

        // Ctrl + Shift + 7 -> Numbered List
        if (isModifier && shiftKey && key === "7") {
          event.preventDefault()
          editor.dispatchCommand(INSERT_ORDERED_LIST_COMMAND, undefined)
          return true
        }

        // Ctrl + Shift + 8 -> Bullet List
        if (isModifier && shiftKey && key === "8") {
          event.preventDefault()
          editor.dispatchCommand(INSERT_UNORDERED_LIST_COMMAND, undefined)
          return true
        }

        // Ctrl + Shift + 9 -> Check List
        if (isModifier && shiftKey && key === "9") {
          event.preventDefault()
          editor.dispatchCommand(INSERT_CHECK_LIST_COMMAND, undefined)
          return true
        }

        // Ctrl + Alt + C -> Code Block
        if (isModifier && altKey && (key === "c" || key === "C")) {
          event.preventDefault()
          formatCode(editor, "")
          return true
        }

        // Ctrl + Shift + Q -> Quote
        if (isModifier && shiftKey && (key === "q" || key === "Q")) {
          event.preventDefault()
          formatQuote(editor, "")
          return true
        }

        // Ctrl + Shift + . -> Increase Font Size
        if (isModifier && shiftKey && (key === "." || key === ">")) {
          event.preventDefault()
          updateFontSize(editor, UpdateFontSizeType.increment, 16)
          return true
        }

        // Ctrl + Shift + , -> Decrease Font Size
        if (isModifier && shiftKey && (key === "," || key === "<")) {
          event.preventDefault()
          updateFontSize(editor, UpdateFontSizeType.decrement, 16)
          return true
        }

        return false
      },
      COMMAND_PRIORITY_NORMAL
    )

    // 3. Window keydown fallback for Ctrl + /
    const handleWindowKeyDown = (event: KeyboardEvent) => {
      if (
        (event.ctrlKey || event.metaKey) &&
        (event.key === "/" || event.key === "?")
      ) {
        const rootElement = editor.getRootElement()
        if (
          rootElement &&
          (rootElement.contains(document.activeElement) ||
            document.activeElement === rootElement)
        ) {
          event.preventDefault()
          setIsDialogOpen(true)
        }
      }
    }
    window.addEventListener("keydown", handleWindowKeyDown)

    return () => {
      unregisterOpenCommand()
      unregisterKeyDown()
      window.removeEventListener("keydown", handleWindowKeyDown)
    }
  }, [editor])

  return (
    <KeyboardShortcutsDialog
      open={isDialogOpen}
      onOpenChange={setIsDialogOpen}
    />
  )
}

import { Command, Keyboard, Search, Sparkles, X } from "lucide-react"
import * as React from "react"

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "../../components/ui/dialog"
import { cn } from "../../utils/cn"
import type { ShortcutCategory } from "./shortcuts-data"
import { SHORTCUT_CATEGORIES, SHORTCUTS_DATA } from "./shortcuts-data"

export function KeyboardShortcutsDialog({
  open,
  onOpenChange,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
}) {
  const [platform, setPlatform] = React.useState<"mac" | "windows">("windows")
  const [searchQuery, setSearchQuery] = React.useState("")
  const [selectedCategory, setSelectedCategory] = React.useState<
    ShortcutCategory | "all"
  >("all")

  // Detect OS on initial mount
  React.useEffect(() => {
    if (typeof window !== "undefined") {
      const isMac = /Mac|iPod|iPhone|iPad/.test(navigator.userAgent)
      setPlatform(isMac ? "mac" : "windows")
    }
  }, [])

  const filteredShortcuts = React.useMemo(() => {
    const query = searchQuery.trim().toLowerCase()
    return SHORTCUTS_DATA.filter((item) => {
      // Category filter
      if (selectedCategory !== "all" && item.category !== selectedCategory) {
        return false
      }
      // Search filter
      if (!query) return true
      return (
        item.action.toLowerCase().includes(query) ||
        item.description.toLowerCase().includes(query) ||
        item.windows.join(" ").toLowerCase().includes(query) ||
        item.mac.join(" ").toLowerCase().includes(query)
      )
    })
  }, [searchQuery, selectedCategory])

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex max-h-[85vh] w-[95vw] max-w-xl flex-col overflow-hidden border border-border/80 bg-background/95 p-0 shadow-2xl backdrop-blur-xl sm:max-w-xl sm:rounded-2xl">
        {/* Header with Title & Platform Switcher */}
        <DialogHeader className="w-full min-w-0 space-y-3 border-b border-border/50 bg-muted/20 px-5 pt-5 pb-3">
          <div className="flex items-center gap-3">
            <div className="flex size-9 shrink-0 items-center justify-center rounded-xl border border-primary/20 bg-primary/10 text-primary shadow-xs">
              <Keyboard className="size-5" />
            </div>
            <div className="min-w-0 flex-1">
              <DialogTitle className="text-base font-semibold tracking-tight text-foreground">
                Keyboard shortcuts
              </DialogTitle>
              <DialogDescription className="mt-0.5 truncate text-xs text-muted-foreground">
                Fast typing and structural editing shortcuts for your workspace
              </DialogDescription>
            </div>
          </div>

          {/* Platform Switcher Segmented Control (macOS vs Windows) */}
          <div className="grid w-full grid-cols-2 gap-1 rounded-lg border border-border/60 bg-muted/50 p-1 shadow-2xs">
            <button
              type="button"
              onClick={() => setPlatform("mac")}
              className={cn(
                "flex cursor-pointer items-center justify-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-semibold transition-all duration-150",
                platform === "mac"
                  ? "bg-background text-foreground shadow-xs"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Command className="size-3.5" />
              <span>macOS</span>
            </button>
            <button
              type="button"
              onClick={() => setPlatform("windows")}
              className={cn(
                "flex cursor-pointer items-center justify-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-semibold transition-all duration-150",
                platform === "windows"
                  ? "bg-background text-foreground shadow-xs"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              <svg
                className="size-3 fill-current text-blue-500"
                viewBox="0 0 24 24"
              >
                <path d="M0 3.449L9.75 2.1v9.451H0m10.949-9.602L24 0v11.4H10.949M0 12.6h9.75v9.451L0 20.699M10.949 12.6H24V24l-12.9-1.801" />
              </svg>
              <span>Windows / Linux</span>
            </button>
          </div>

          {/* Search Bar & Category Filters */}
          <div className="w-full min-w-0 space-y-2">
            <div className="relative w-full">
              <Search className="absolute top-1/2 left-3 size-3.5 -translate-y-1/2 text-muted-foreground" />
              <input
                type="text"
                placeholder="Search shortcuts (e.g. heading, list, code, font, bold)..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full rounded-lg border border-input bg-background/80 py-1.5 pr-8 pl-9 text-xs transition-all outline-none placeholder:text-muted-foreground/60 focus:border-primary/50 focus:ring-2 focus:ring-primary/20"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery("")}
                  className="absolute top-1/2 right-2.5 flex size-4 -translate-y-1/2 cursor-pointer items-center justify-center text-muted-foreground hover:text-foreground"
                >
                  <X className="size-3" />
                </button>
              )}
            </div>

            {/* Category Filter Pills */}
            <div className="flex w-full min-w-0 scrollbar-none items-center gap-1 overflow-x-auto pb-0.5">
              {SHORTCUT_CATEGORIES.map((cat) => {
                const isActive = selectedCategory === cat.id
                return (
                  <button
                    key={cat.id}
                    type="button"
                    onClick={() => setSelectedCategory(cat.id)}
                    className={cn(
                      "shrink-0 cursor-pointer rounded-md px-2.5 py-1 text-[11px] font-medium whitespace-nowrap transition-all",
                      isActive
                        ? "bg-primary text-primary-foreground shadow-xs"
                        : "text-muted-foreground hover:bg-muted/60 hover:text-foreground"
                    )}
                  >
                    {cat.label}
                  </button>
                )
              })}
            </div>
          </div>
        </DialogHeader>

        {/* Shortcuts Table */}
        <div className="w-full min-w-0 flex-1 overflow-x-hidden overflow-y-auto px-5 py-2">
          {/* Table Header */}
          <div className="sticky top-0 z-10 grid grid-cols-[1fr_auto] items-center border-b border-border/50 bg-background/95 px-1 py-2 text-[11px] font-semibold tracking-wider text-muted-foreground uppercase backdrop-blur-xs">
            <span>ACTION</span>
            <span>SHORTCUT</span>
          </div>

          {filteredShortcuts.length > 0 ? (
            <div className="w-full min-w-0 divide-y divide-border/30">
              {filteredShortcuts.map((item) => {
                const keys = platform === "mac" ? item.mac : item.windows
                return (
                  <div
                    key={item.id}
                    className="group grid grid-cols-[1fr_auto] items-center gap-3 rounded-lg px-1 py-2 transition-colors hover:bg-muted/40"
                  >
                    {/* Left: Action & Description */}
                    <div className="min-w-0 pr-2">
                      <div className="flex flex-wrap items-center gap-1.5">
                        <span className="text-xs font-semibold text-foreground">
                          {item.action}
                        </span>
                        {item.badge && (
                          <span
                            className={cn(
                              "py-0.2 rounded-md border px-1.5 text-[9px] font-semibold",
                              item.badge === "Popular" &&
                                "border-primary/20 bg-primary/10 text-primary",
                              item.badge === "Markdown" &&
                                "border-amber-500/20 bg-amber-500/10 text-amber-600 dark:text-amber-400",
                              item.badge === "Developer" &&
                                "border-emerald-500/20 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400",
                              item.badge === "Tasks" &&
                                "border-sky-500/20 bg-sky-500/10 text-sky-600 dark:text-sky-400",
                              item.badge === "Help" &&
                                "border-purple-500/20 bg-purple-500/10 text-purple-600 dark:text-purple-400",
                              item.badge === "Essential" &&
                                "border-rose-500/20 bg-rose-500/10 text-rose-600 dark:text-rose-400"
                            )}
                          >
                            {item.badge}
                          </span>
                        )}
                      </div>
                      <p className="mt-0.5 truncate text-[11px] text-muted-foreground">
                        {item.description}
                      </p>
                    </div>

                    {/* Right: Key Combination */}
                    <div className="flex shrink-0 items-center justify-end gap-1">
                      {keys.map((k, idx) => (
                        <React.Fragment key={idx}>
                          {idx > 0 && (
                            <span className="text-[10px] font-semibold text-muted-foreground/70 select-none">
                              +
                            </span>
                          )}
                          <kbd className="inline-flex h-6 min-w-[24px] items-center justify-center rounded-md border border-border/90 bg-muted/70 px-1.5 py-0.5 font-mono text-[11px] font-semibold text-foreground shadow-2xs group-hover:border-border group-hover:bg-muted">
                            {k}
                          </kbd>
                        </React.Fragment>
                      ))}
                    </div>
                  </div>
                )
              })}
            </div>
          ) : (
            <div className="space-y-1 py-12 text-center text-muted-foreground">
              <Search className="mx-auto size-6 text-muted-foreground/40" />
              <div className="text-xs font-medium">No shortcuts found</div>
              <div className="text-[11px] opacity-70">
                Try searching for another keyword or switch category
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex w-full min-w-0 items-center justify-between border-t border-border/50 bg-muted/10 px-5 py-2.5 text-[11px] text-muted-foreground">
          <div className="flex items-center gap-1.5 truncate pr-2">
            <Sparkles className="size-3.5 shrink-0 text-primary" />
            <span className="truncate">
              Tip: Press{" "}
              <kbd className="rounded border border-border/80 bg-background px-1.5 py-0.5 font-mono font-semibold text-foreground">
                {platform === "mac" ? "⌘" : "Ctrl"} + /
              </kbd>{" "}
              anytime in the editor
            </span>
          </div>
          <span className="shrink-0 font-mono text-[10px] opacity-70">
            {filteredShortcuts.length} of {SHORTCUTS_DATA.length}
          </span>
        </div>
      </DialogContent>
    </Dialog>
  )
}

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext"
import {
  $getNearestNodeFromDOMNode,
  COMMAND_PRIORITY_HIGH,
  DRAGOVER_COMMAND,
  DROP_COMMAND,
} from "lexical"
import * as React from "react"

import { insertBlockIntoEditor } from "./insert-helpers"
import type { SidebarInsertBlockType } from "./types"

export const DRAG_DATA_FORMAT = "application/x-lexical-block"

export function DragDropPlugin() {
  const [editor] = useLexicalComposerContext()
  const indicatorRef = React.useRef<HTMLDivElement | null>(null)

  React.useEffect(() => {
    // Create floating drop line indicator element
    const indicator = document.createElement("div")
    indicator.className =
      "pointer-events-none absolute z-40 hidden h-0.5 rounded-full bg-primary shadow-[0_0_8px_rgba(59,130,246,0.6)] transition-all duration-75"
    document.body.appendChild(indicator)
    indicatorRef.current = indicator

    const hideIndicator = () => {
      if (indicatorRef.current) {
        indicatorRef.current.style.display = "none"
      }
    }

    const unregisterDragOver = editor.registerCommand<DragEvent>(
      DRAGOVER_COMMAND,
      (event) => {
        const hasBlockData =
          event.dataTransfer?.types.includes(DRAG_DATA_FORMAT) ||
          event.dataTransfer?.types.includes("text/plain")

        if (!hasBlockData) return false

        event.preventDefault()

        const rootElement = editor.getRootElement()
        if (!rootElement) return false

        const target = document.elementFromPoint(
          event.clientX,
          event.clientY
        ) as HTMLElement | null

        if (target && rootElement.contains(target)) {
          // Find top-level block inside root
          let blockElement: HTMLElement | null = target
          while (
            blockElement &&
            blockElement.parentElement &&
            blockElement.parentElement !== rootElement
          ) {
            blockElement = blockElement.parentElement
          }

          if (blockElement && indicatorRef.current) {
            const rect = blockElement.getBoundingClientRect()
            const isBottomHalf = event.clientY > rect.top + rect.height / 2
            const topPos = isBottomHalf ? rect.bottom : rect.top

            indicatorRef.current.style.display = "block"
            indicatorRef.current.style.top = `${topPos + window.scrollY}px`
            indicatorRef.current.style.left = `${rect.left + window.scrollX}px`
            indicatorRef.current.style.width = `${rect.width}px`
          }
        }

        return true
      },
      COMMAND_PRIORITY_HIGH
    )

    const unregisterDrop = editor.registerCommand<DragEvent>(
      DROP_COMMAND,
      (event) => {
        hideIndicator()
        const blockType = event.dataTransfer?.getData(DRAG_DATA_FORMAT) as
          SidebarInsertBlockType | undefined

        if (!blockType) return false

        event.preventDefault()

        const rootElement = editor.getRootElement()
        if (!rootElement) return false

        const target = document.elementFromPoint(
          event.clientX,
          event.clientY
        ) as HTMLElement | null

        editor.update(() => {
          let targetNode = null
          if (target) {
            const domNode = target
            const nearestNode = $getNearestNodeFromDOMNode(domNode)
            if (nearestNode) {
              targetNode = nearestNode.getTopLevelElement()
            }
          }

          insertBlockIntoEditor(editor, blockType, targetNode)
        })

        return true
      },
      COMMAND_PRIORITY_HIGH
    )

    const handleDragLeave = (e: DragEvent) => {
      const rootElement = editor.getRootElement()
      if (rootElement && !rootElement.contains(e.relatedTarget as Node)) {
        hideIndicator()
      }
    }

    const rootElement = editor.getRootElement()
    rootElement?.addEventListener("dragleave", handleDragLeave)

    return () => {
      unregisterDragOver()
      unregisterDrop()
      rootElement?.removeEventListener("dragleave", handleDragLeave)
      if (indicator.parentElement) {
        indicator.parentElement.removeChild(indicator)
      }
    }
  }, [editor])

  return null
}

import { $createCodeNode } from "@lexical/code"
import { INSERT_HORIZONTAL_RULE_COMMAND } from "@lexical/extension"
import {
  INSERT_CHECK_LIST_COMMAND,
  INSERT_ORDERED_LIST_COMMAND,
  INSERT_UNORDERED_LIST_COMMAND,
} from "@lexical/list"
import { $createHeadingNode, $createQuoteNode } from "@lexical/rich-text"
import { INSERT_TABLE_COMMAND } from "@lexical/table"
import type { ElementNode, LexicalEditor, LexicalNode } from "lexical"
import {
  $createParagraphNode,
  $createTextNode,
  $getRoot,
  $getSelection,
  $isRangeSelection,
} from "lexical"

import { INSERT_COLLAPSIBLE_COMMAND } from "../../nodes/collapsible-nodes"
import { INSERT_EQUATION_COMMAND } from "../../nodes/equation-node"
import { INSERT_EXCALIDRAW_COMMAND } from "../../nodes/excalidraw-node"
import { OPEN_IMAGE_DIALOG_COMMAND } from "../../nodes/image-node"
import { OPEN_LAYOUT_DIALOG_COMMAND } from "../../nodes/layout-nodes"
import { INSERT_PAGE_BREAK_COMMAND } from "../../nodes/page-break-node"
import { INSERT_POLL_COMMAND } from "../../nodes/poll-node"
import { INSERT_STICKY_COMMAND } from "../../nodes/sticky-node"
import {
  INSERT_FIGMA_COMMAND,
  INSERT_TWEET_COMMAND,
  INSERT_YOUTUBE_COMMAND,
} from "../auto-embed"
import type { SidebarInsertBlockType } from "./types"

export function insertBlockIntoEditor(
  editor: LexicalEditor,
  blockType: SidebarInsertBlockType,
  targetNode?: LexicalNode | null
) {
  editor.update(() => {
    let newNode: ElementNode | null = null

    switch (blockType) {
      case "text": {
        newNode = $createParagraphNode()
        newNode.append($createTextNode("New paragraph text..."))
        break
      }
      case "h1": {
        newNode = $createHeadingNode("h1")
        newNode.append($createTextNode("Heading 1"))
        break
      }
      case "h2": {
        newNode = $createHeadingNode("h2")
        newNode.append($createTextNode("Heading 2"))
        break
      }
      case "h3": {
        newNode = $createHeadingNode("h3")
        newNode.append($createTextNode("Heading 3"))
        break
      }
      case "card":
      case "page": {
        newNode = $createQuoteNode()
        newNode.append(
          $createTextNode("📌 Note Card / Callout block content...")
        )
        break
      }
      case "code": {
        newNode = $createCodeNode("javascript")
        newNode.append(
          $createTextNode(
            '// Write your code here\nconsole.log("Hello NoteFlow!");'
          )
        )
        break
      }
      case "mermaid": {
        newNode = $createCodeNode("mermaid")
        newNode.append(
          $createTextNode(
            "graph TD;\n  A[Start] --> B{Process};\n  B -->|Yes| C[Done];\n  B -->|No| D[Retry];"
          )
        )
        break
      }
      case "gallery":
      case "kanban":
      case "file": {
        newNode = $createQuoteNode()
        const label =
          blockType === "gallery"
            ? "🖼️ Media Gallery"
            : blockType === "kanban"
              ? "📋 Kanban Board"
              : "📎 File Attachment"
        newNode.append($createTextNode(`[${label}] - Click to configure`))
        break
      }
      default:
        break
    }

    if (newNode) {
      if (targetNode) {
        targetNode.insertAfter(newNode)
        newNode.select()
      } else {
        const selection = $getSelection()
        if ($isRangeSelection(selection)) {
          const anchor = selection.anchor.getNode()
          const topElement = anchor.getTopLevelElement()
          if (topElement) {
            topElement.insertAfter(newNode)
          } else {
            $getRoot().append(newNode)
          }
          newNode.select()
        } else {
          $getRoot().append(newNode)
          newNode.select()
        }
      }
      return
    }

    // Commands based insertions
    switch (blockType) {
      case "table": {
        editor.dispatchCommand(INSERT_TABLE_COMMAND, {
          columns: "3",
          rows: "3",
          includeHeaders: true,
        })
        break
      }
      case "line-solid":
      case "line-dashed":
      case "line-dotted": {
        editor.dispatchCommand(INSERT_HORIZONTAL_RULE_COMMAND, undefined)
        break
      }
      case "page-break": {
        editor.dispatchCommand(INSERT_PAGE_BREAK_COMMAND, undefined)
        break
      }
      case "bullet-list": {
        editor.dispatchCommand(INSERT_UNORDERED_LIST_COMMAND, undefined)
        break
      }
      case "numbered-list": {
        editor.dispatchCommand(INSERT_ORDERED_LIST_COMMAND, undefined)
        break
      }
      case "checklist": {
        editor.dispatchCommand(INSERT_CHECK_LIST_COMMAND, undefined)
        break
      }
      case "image":
      case "image-unsplash": {
        editor.dispatchCommand(OPEN_IMAGE_DIALOG_COMMAND, undefined)
        break
      }
      case "tex": {
        editor.dispatchCommand(INSERT_EQUATION_COMMAND, {
          equation:
            "f(x) = \\int_{-\\infty}^{\\infty} \\hat{f}(\\xi)\\,e^{2 \\pi i \\xi x} \\, d\\xi",
          inline: false,
        })
        break
      }
      case "whiteboard": {
        editor.dispatchCommand(INSERT_EXCALIDRAW_COMMAND, undefined)
        break
      }
      case "poll": {
        editor.dispatchCommand(INSERT_POLL_COMMAND, {
          question: "What is your preferred note workflow?",
          options: [
            "Notion-style Docs",
            "Whiteboard & Mindmap",
            "Markdown & LaTeX",
          ],
        })
        break
      }
      case "collapsible": {
        editor.dispatchCommand(INSERT_COLLAPSIBLE_COMMAND, undefined)
        break
      }
      case "columns": {
        editor.dispatchCommand(OPEN_LAYOUT_DIALOG_COMMAND, undefined)
        break
      }
      case "sticky": {
        editor.dispatchCommand(INSERT_STICKY_COMMAND, undefined)
        break
      }
      case "youtube": {
        editor.dispatchCommand(
          INSERT_YOUTUBE_COMMAND,
          "https://www.youtube.com/watch?v=dQw4w9WgXcQ"
        )
        break
      }
      case "figma": {
        editor.dispatchCommand(
          INSERT_FIGMA_COMMAND,
          "https://www.figma.com/file/LKQ4FJ4bTnCSjedbRpk931/Sample-File"
        )
        break
      }
      case "tweet": {
        editor.dispatchCommand(
          INSERT_TWEET_COMMAND,
          "https://x.com/lexicaljs/status/1514339965042655234"
        )
        break
      }
      default:
        break
    }
  })
}

