import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext"
import {
  $getTableColumnIndexFromTableCellNode,
  $getTableNodeFromLexicalNodeOrThrow,
  $isTableCellNode,
  $isTableRowNode,
} from "@lexical/table"
import { $getNearestNodeFromDOMNode } from "lexical"
import * as React from "react"
import { createPortal } from "react-dom"

interface ResizerState {
  cellDom: HTMLElement
  tableDom: HTMLElement
  lineLeft: number
  tableTop: number
  tableHeight: number
  startClientX: number
  startWidth: number
  currentWidth: number
}

const MIN_COLUMN_WIDTH = 45

export function TableCellResizerPlugin(): React.JSX.Element | null {
  const [editor] = useLexicalComposerContext()
  const [activeHandle, setActiveHandle] = React.useState<{
    cellDom: HTMLElement
    tableDom: HTMLElement
    x: number
    top: number
    height: number
  } | null>(null)
  const [resizing, setResizing] = React.useState<ResizerState | null>(null)

  // Track hover near right edge of cells
  React.useEffect(() => {
    const root = editor.getRootElement()
    if (!root || resizing) return

    let clearTimer: ReturnType<typeof setTimeout> | null = null

    const handleMouseMove = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null
      if (!target) return

      const cell = target.closest("td, th")
      const table = cell?.closest("table")

      if (
        cell instanceof HTMLElement &&
        table instanceof HTMLElement &&
        root.contains(cell)
      ) {
        const cellRect = cell.getBoundingClientRect()
        const tableRect = table.getBoundingClientRect()

        // Check if mouse is near the right boundary of the cell (within 7px)
        const isNearRightEdge =
          Math.abs(e.clientX - cellRect.right) <= 7 &&
          e.clientY >= cellRect.top &&
          e.clientY <= cellRect.bottom

        if (isNearRightEdge) {
          if (clearTimer) clearTimeout(clearTimer)
          setActiveHandle({
            cellDom: cell,
            tableDom: table,
            x: cellRect.right,
            top: tableRect.top,
            height: tableRect.height,
          })
          return
        }
      }

      if (activeHandle) {
        clearTimer = setTimeout(() => {
          setActiveHandle(null)
        }, 150)
      }
    }

    const handleMouseLeave = () => {
      setActiveHandle(null)
    }

    root.addEventListener("mousemove", handleMouseMove)
    root.addEventListener("mouseleave", handleMouseLeave)
    return () => {
      if (clearTimer) clearTimeout(clearTimer)
      root.removeEventListener("mousemove", handleMouseMove)
      root.removeEventListener("mouseleave", handleMouseLeave)
    }
  }, [editor, resizing, activeHandle])

  // Mouse down on handle -> start dragging
  const handleMouseDown = (e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()

    if (!activeHandle) return

    const cellRect = activeHandle.cellDom.getBoundingClientRect()
    const tableRect = activeHandle.tableDom.getBoundingClientRect()

    setResizing({
      cellDom: activeHandle.cellDom,
      tableDom: activeHandle.tableDom,
      lineLeft: activeHandle.x,
      tableTop: tableRect.top,
      tableHeight: tableRect.height,
      startClientX: e.clientX,
      startWidth: cellRect.width,
      currentWidth: cellRect.width,
    })
  }

  // Handle global drag & release
  React.useEffect(() => {
    if (!resizing) return

    const handlePointerMove = (e: MouseEvent) => {
      const deltaX = e.clientX - resizing.startClientX
      const nextWidth = Math.max(resizing.startWidth + deltaX, MIN_COLUMN_WIDTH)

      setResizing((prev) =>
        prev
          ? {
              ...prev,
              lineLeft: prev.lineLeft + (nextWidth - prev.currentWidth),
              currentWidth: nextWidth,
            }
          : null
      )
    }

    const handlePointerUp = () => {
      if (resizing) {
        const finalWidth = resizing.currentWidth
        const targetCellDom = resizing.cellDom

        editor.update(() => {
          const node = $getNearestNodeFromDOMNode(targetCellDom)
          if ($isTableCellNode(node)) {
            try {
              const tableNode = $getTableNodeFromLexicalNodeOrThrow(node)
              const colIdx = $getTableColumnIndexFromTableCellNode(node)

              // Update width across all cells in this column
              const rows = tableNode.getChildren()
              for (const row of rows) {
                if ($isTableRowNode(row)) {
                  const cells = row.getChildren()
                  const colCell = cells[colIdx]
                  if ($isTableCellNode(colCell)) {
                    colCell.setWidth(finalWidth)
                  }
                }
              }
            } catch (err) {
              console.error("[TableCellResizer Error]:", err)
            }
          }
        })
      }

      setResizing(null)
      setActiveHandle(null)
    }

    window.addEventListener("mousemove", handlePointerMove)
    window.addEventListener("mouseup", handlePointerUp)
    return () => {
      window.removeEventListener("mousemove", handlePointerMove)
      window.removeEventListener("mouseup", handlePointerUp)
    }
  }, [resizing, editor])

  // If currently resizing, show the vertical guide line across the table
  if (resizing) {
    return createPortal(
      <div
        className="pointer-events-none fixed z-[9999] select-none"
        style={{
          left: resizing.lineLeft,
          top: resizing.tableTop,
          height: resizing.tableHeight,
          width: "2px",
          backgroundColor: "var(--primary, #3b82f6)",
          boxShadow: "0 0 8px rgba(59, 130, 246, 0.6)",
        }}
      >
        {/* Width tooltip bubble */}
        <div className="absolute -top-7 left-1/2 -translate-x-1/2 rounded bg-zinc-900 px-1.5 py-0.5 font-mono text-[10px] font-semibold text-white shadow">
          {Math.round(resizing.currentWidth)}px
        </div>
      </div>,
      document.body
    )
  }

  // If hovering near right edge, render the hover resizer handle
  if (activeHandle) {
    return createPortal(
      <div
        role="separator"
        aria-orientation="vertical"
        aria-label="Resize column"
        onMouseDown={handleMouseDown}
        className="fixed z-40 w-2 -translate-x-1/2 cursor-col-resize transition-colors select-none hover:bg-primary/50 active:bg-primary"
        style={{
          left: activeHandle.x,
          top: activeHandle.top,
          height: activeHandle.height,
        }}
      >
        <div className="mx-auto h-full w-[2px] bg-primary/40 transition-colors hover:bg-primary" />
      </div>,
      document.body
    )
  }

  return null
}

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext"
import {
  $deleteTableColumn,
  $getTableColumnIndexFromTableCellNode,
  $getTableNodeFromLexicalNodeOrThrow,
  $getTableRowNodeFromTableCellNodeOrThrow,
  $insertTableColumnAtNode,
  $insertTableRowAtNode,
  $isTableCellNode,
} from "@lexical/table"
import { $getNearestNodeFromDOMNode } from "lexical"
import { Plus, Trash2 } from "lucide-react"
import * as React from "react"
import { createPortal } from "react-dom"

interface Position {
  x: number
  y: number
  width: number
  height: number
}

export function TableHoverActionsPlugin(): React.JSX.Element | null {
  const [editor] = useLexicalComposerContext()
  const [hoveredCell, setHoveredCell] = React.useState<{
    dom: HTMLElement
    rect: Position
  } | null>(null)
  const [isMenuHovered, setIsMenuHovered] = React.useState(false)

  React.useEffect(() => {
    const rootElement = editor.getRootElement()
    if (!rootElement) return

    let timeoutId: ReturnType<typeof setTimeout> | null = null

    const handleMouseMove = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null
      if (!target) return

      const cell = target.closest("td, th")
      if (cell && rootElement.contains(cell)) {
        if (timeoutId) clearTimeout(timeoutId)
        const rect = cell.getBoundingClientRect()
        setHoveredCell({
          dom: cell as HTMLElement,
          rect: {
            x: rect.left,
            y: rect.top,
            width: rect.width,
            height: rect.height,
          },
        })
      } else {
        if (!isMenuHovered) {
          timeoutId = setTimeout(() => {
            setHoveredCell(null)
          }, 400)
        }
      }
    }

    const handleMouseLeave = () => {
      if (!isMenuHovered) {
        timeoutId = setTimeout(() => {
          setHoveredCell(null)
        }, 300)
      }
    }

    rootElement.addEventListener("mousemove", handleMouseMove)
    rootElement.addEventListener("mouseleave", handleMouseLeave)

    return () => {
      if (timeoutId) clearTimeout(timeoutId)
      rootElement.removeEventListener("mousemove", handleMouseMove)
      rootElement.removeEventListener("mouseleave", handleMouseLeave)
    }
  }, [editor, isMenuHovered])

  if (!hoveredCell) return null

  const insertRow = (after: boolean) => {
    editor.update(() => {
      const node = $getNearestNodeFromDOMNode(hoveredCell.dom)
      if ($isTableCellNode(node)) {
        $insertTableRowAtNode(node, after)
      }
    })
  }

  const deleteRow = () => {
    editor.update(() => {
      const node = $getNearestNodeFromDOMNode(hoveredCell.dom)
      if ($isTableCellNode(node)) {
        try {
          const row = $getTableRowNodeFromTableCellNodeOrThrow(node)
          row.remove()
        } catch {}
      }
    })
    setHoveredCell(null)
  }

  const insertCol = (after: boolean) => {
    editor.update(() => {
      const node = $getNearestNodeFromDOMNode(hoveredCell.dom)
      if ($isTableCellNode(node)) {
        $insertTableColumnAtNode(node, after, true)
      }
    })
  }

  const deleteCol = () => {
    editor.update(() => {
      const node = $getNearestNodeFromDOMNode(hoveredCell.dom)
      if ($isTableCellNode(node)) {
        try {
          const table = $getTableNodeFromLexicalNodeOrThrow(node)
          const colIdx = $getTableColumnIndexFromTableCellNode(node)
          $deleteTableColumn(table, colIdx)
        } catch {}
      }
    })
    setHoveredCell(null)
  }

  return createPortal(
    <div
      onMouseEnter={() => setIsMenuHovered(true)}
      onMouseLeave={() => {
        setIsMenuHovered(false)
        setHoveredCell(null)
      }}
      className="pointer-events-auto fixed z-50 transition-opacity duration-150"
      style={{
        left: hoveredCell.rect.x,
        top: hoveredCell.rect.y,
        width: hoveredCell.rect.width,
        height: hoveredCell.rect.height,
        pointerEvents: "none",
      }}
    >
      {/* Column Insert (Top Button) */}
      <div
        className="pointer-events-auto absolute -top-3 left-1/2 flex -translate-x-1/2 items-center gap-0.5 rounded-full border border-border/80 bg-background/95 px-1 py-0.5 shadow-xs backdrop-blur-xs transition-transform hover:scale-110"
        title="Column actions"
      >
        <button
          type="button"
          onClick={() => insertCol(false)}
          className="flex size-4 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-muted hover:text-foreground"
          title="Insert column left"
        >
          <Plus className="size-3" />
        </button>
        <button
          type="button"
          onClick={() => insertCol(true)}
          className="flex size-4 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-muted hover:text-foreground"
          title="Insert column right"
        >
          <Plus className="size-3" />
        </button>
        <button
          type="button"
          onClick={deleteCol}
          className="flex size-4 cursor-pointer items-center justify-center rounded-full text-destructive/70 hover:bg-destructive/10 hover:text-destructive"
          title="Delete column"
        >
          <Trash2 className="size-2.5" />
        </button>
      </div>

      {/* Row Insert (Left Button) */}
      <div
        className="pointer-events-auto absolute top-1/2 -left-3 flex -translate-y-1/2 flex-col items-center gap-0.5 rounded-full border border-border/80 bg-background/95 p-0.5 shadow-xs backdrop-blur-xs transition-transform hover:scale-110"
        title="Row actions"
      >
        <button
          type="button"
          onClick={() => insertRow(false)}
          className="flex size-4 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-muted hover:text-foreground"
          title="Insert row above"
        >
          <Plus className="size-3" />
        </button>
        <button
          type="button"
          onClick={() => insertRow(true)}
          className="flex size-4 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-muted hover:text-foreground"
          title="Insert row below"
        >
          <Plus className="size-3" />
        </button>
        <button
          type="button"
          onClick={deleteRow}
          className="flex size-4 cursor-pointer items-center justify-center rounded-full text-destructive/70 hover:bg-destructive/10 hover:text-destructive"
          title="Delete row"
