import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext"
import { $isHeadingNode } from "@lexical/rich-text"
import type { NodeKey } from "lexical"
import { $getRoot } from "lexical"
import { ListTree, X } from "lucide-react"
import * as React from "react"

export interface TableOfContentsEntry {
  key: NodeKey
  text: string
  tag: "h1" | "h2" | "h3"
}

export function TableOfContentsPlugin(): React.JSX.Element | null {
  const [editor] = useLexicalComposerContext()
  const [headings, setHeadings] = React.useState<TableOfContentsEntry[]>([])
  const [isOpen, setIsOpen] = React.useState(false)

  React.useEffect(() => {
    return editor.registerUpdateListener(({ editorState }) => {
      editorState.read(() => {
        const root = $getRoot()
        const newHeadings: TableOfContentsEntry[] = []

        for (const child of root.getChildren()) {
          if ($isHeadingNode(child)) {
            const tag = child.getTag() as "h1" | "h2" | "h3"
            const text = child.getTextContent()
            if (text.trim()) {
              newHeadings.push({
                key: child.getKey(),
                text,
                tag,
              })
            }
          }
        }
        setHeadings(newHeadings)
      })
    })
  }, [editor])

  const scrollToHeading = (key: NodeKey) => {
    const element = editor.getElementByKey(key)
    if (element) {
      element.scrollIntoView({ behavior: "smooth", block: "center" })
    }
  }

  if (headings.length === 0) return null

  return (
    <div className="absolute top-3 right-3 z-30 flex flex-col items-end">
      {!isOpen ? (
        <button
          type="button"
          onClick={() => setIsOpen(true)}
          className="flex size-8 cursor-pointer items-center justify-center rounded-lg border border-border/80 bg-background/90 text-muted-foreground shadow-xs backdrop-blur-xs transition-all hover:bg-muted hover:text-foreground"
          title="Table of Contents"
        >
          <ListTree className="size-4" />
        </button>
      ) : (
        <div className="w-56 animate-in rounded-xl border border-border/80 bg-background/95 p-3 shadow-lg backdrop-blur-md transition-all zoom-in-95 fade-in">
          <div className="mb-2 flex items-center justify-between border-b border-border/50 pb-2">
            <span className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
              <ListTree className="size-3.5 text-primary" />
              Table of Contents
            </span>
            <button
              type="button"
              onClick={() => setIsOpen(false)}
              className="flex size-5 cursor-pointer items-center justify-center rounded-sm text-muted-foreground hover:bg-muted hover:text-foreground"
            >
              <X className="size-3" />
            </button>
          </div>
          <div className="max-h-60 space-y-1 overflow-y-auto pr-1 text-xs">
            {headings.map((h) => (
              <button
                key={h.key}
                type="button"
                onClick={() => scrollToHeading(h.key)}
                className={`block w-full truncate rounded-md px-2 py-1 text-left transition-colors hover:bg-muted hover:text-foreground ${
                  h.tag === "h1"
                    ? "font-semibold text-foreground"
                    : h.tag === "h2"
                      ? "pl-4 text-muted-foreground"
                      : "pl-6 text-muted-foreground/80"
                }`}
              >
                {h.text}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

import { $isCodeNode, CodeNode } from "@lexical/code"
import { $getNearestNodeOfType } from "@lexical/utils"
import type { LexicalEditor } from "lexical"
import { $getNodeByKey, $getSelection, $isRangeSelection } from "lexical"
import { Check, ChevronDown } from "lucide-react"
import * as React from "react"

import {
  getCodeLanguageOptions,
  getLanguageFriendlyName,
} from "../../../utils/code-languages"

import { Button } from "../../../components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "../../../components/ui/dropdown-menu"
import { cn } from "../../../utils/cn"

export interface CodeLanguageDropdownProps {
  editor: LexicalEditor
  codeLanguage: string
  codeNodeKey?: string | null
  disabled?: boolean
}

export function CodeLanguageDropdown({
  editor,
  codeLanguage,
  codeNodeKey,
  disabled = false,
}: CodeLanguageDropdownProps) {
  const codeLanguageOptions = React.useMemo(() => getCodeLanguageOptions(), [])

  const displayLabel = React.useMemo(() => {
    if (!codeLanguage) return "(No language)"
    return getLanguageFriendlyName(codeLanguage) || codeLanguage
  }, [codeLanguage])

  const handleSelectLanguage = React.useCallback(
    (newLang: string) => {
      editor.update(() => {
        let targetCodeNode: CodeNode | null = null

        if (codeNodeKey) {
          const node = $getNodeByKey(codeNodeKey)
          if ($isCodeNode(node)) {
            targetCodeNode = node
          }
        }

        if (!targetCodeNode) {
          const selection = $getSelection()
          if ($isRangeSelection(selection)) {
            const anchorNode = selection.anchor.getNode()
            const parent = anchorNode.getParent()
            const candidate = $isCodeNode(anchorNode)
              ? anchorNode
              : $getNearestNodeOfType(anchorNode, CodeNode) ||
                ($isCodeNode(parent) ? parent : null)
            if ($isCodeNode(candidate)) {
              targetCodeNode = candidate
            }
          }
        }

        if (targetCodeNode) {
          targetCodeNode.setLanguage(newLang)
        }
      })
    },
    [editor, codeNodeKey]
  )

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="sm"
          disabled={disabled}
          className="h-7 gap-1.5 rounded-md px-2 text-[11px] font-medium hover:bg-background/80"
          title="Select code language"
        >
          <span className="max-w-[100px] truncate text-foreground/80">
            {displayLabel}
          </span>
          <ChevronDown className="ml-0.5 h-3 w-3 opacity-40" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="start"
        className="max-h-72 w-44 scrollbar-thin overflow-y-auto"
      >
        <DropdownMenuItem
          onClick={() => handleSelectLanguage("")}
          className={cn(
            "cursor-pointer text-xs",
            !codeLanguage && "bg-primary/8 font-medium text-primary"
          )}
        >
          <span className="flex-1">(No language)</span>
          {!codeLanguage && (
            <Check className="ml-auto h-3.5 w-3.5 text-primary" />
          )}
        </DropdownMenuItem>

        {codeLanguageOptions.map(([langKey, friendlyName]) => {
          const isSelected =
            codeLanguage === langKey ||
            (langKey === "js" && codeLanguage === "javascript") ||
            (langKey === "ts" && codeLanguage === "typescript") ||
            (langKey === "py" && codeLanguage === "python")

          return (
            <DropdownMenuItem
              key={langKey}
              onClick={() => handleSelectLanguage(langKey)}
              className={cn(
                "cursor-pointer text-xs",
                isSelected && "bg-primary/8 font-medium text-primary"
              )}
            >
              <span className="flex-1">{friendlyName}</span>
              {isSelected && (
                <Check className="ml-auto h-3.5 w-3.5 text-primary" />
              )}
            </DropdownMenuItem>
          )
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

